			if tokenRepeat > 30 {
				slog.Debug("prediction aborted, token repeat limit reached")
				return ctx.Err()
			}

			if c.Done {
				fn(c)
				return nil
			}

			if c.Content != "" || c.Thinking != "" || len(c.ToolCalls) > 0 {
