	w.Lock.Lock()
	defer w.Lock.Unlock()
	return w.ServerDone
}

func (w *WshRpc) setServerDone() {
	w.Lock.Lock()
	defer w.Lock.Unlock()
	w.ServerDone = true
	close(w.CtxDoneCh)
	for range w.CtxDoneCh {
		// drain channel
	}
}

func (w *WshRpc) retrySendTimeout(resId string) {
	for {
		done := func() bool {
			w.Lock.Lock()
			defer w.Lock.Unlock()
			if w.ServerDone {
				return true
			}
			select {
			case w.CtxDoneCh <- resId:
				return true
			default:
				return false
			}
		}()
		if done {
			return
		}
		time.Sleep(100 * time.Millisecond)
	}

}

