	ctx         context.Context
	reqId       string
	respCh      chan *RpcMessage
}

func EnsureConnection(ctx context.Context, connName string) error {
	if connName == "" {
		return nil
	}
	conn := GetWslConn(connName)
	if conn == nil {
		return fmt.Errorf("connection not found: %s", connName)
	}
	connStatus := conn.DeriveConnStatus()
	switch connStatus.Status {
	case Status_Connected:
		return nil
	case Status_Connecting:
		return conn.WaitForConnect(ctx)
	case Status_Init, Status_Disconnected:
		return conn.Connect(ctx)
	case Status_Error:
		return fmt.Errorf("connection error: %s", connStatus.Error)
	default:
		return fmt.Errorf("unknown connection status %q", connStatus.Status)
	}
}

async def _setup_builtin_browser(self, playwright: Playwright) -> PlaywrightBrowser:
	"""Sets up and returns a Playwright Browser instance with anti-detection measures."""
	assert self.config.browser_binary_path is None, 'browser_binary_path should be None if trying to use the builtin browsers'

	if self.config.headless:
		screen_size = {'width': 1920, 'height': 1080}
		offset_x, offset_y = 0, 0
	else:
		screen_size = get_screen_resolution()
		offset_x, offset_y = get_window_adjustments()

	chrome_args = {
		CHROME_DEBUGGING_ARG % {'chrome_remote_debugging_port': self.config.chrome_remote_debugging_port},
		*CHROME_ARGS,
		*(CHROME_DOCKER_ARGS if IN_DOCKER else []),
		*(CHROME_HEADLESS_ARGS if self.config.headless else []),
		*(CHROME_DISABLE_SECURITY_ARGS if self.config.disable_security else []),
		*(CHROME_DETERMINISTIC_RENDERING_ARGS if self.config.deterministic_rendering else []),
		f'--window-position={offset_x},{offset_y}',
		f'--window-size={screen_size["width"]},{screen_size["height"]}',
		*self.config.extra_browser_args,
	}

	# check if chrome remote debugging port is already taken,
	# if so remove the remote-debugging-port arg to prevent conflicts
	with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
		if s.connect_ex(('localhost', self.config.chrome_remote_debugging_port)) == 0:
			chrome_args.remove(f'--remote-debugging-port={self.config.chrome_remote_debugging_port}')

	browser_class = getattr(playwright, self.config.browser_class)
	args = {
		'chromium': list(chrome_args),
		'firefox': [
			*{
				'-no-remote',
				*self.config.extra_browser_args,
			}
		],
		'webkit': [
			*{
				'--no-startup-window',
				*self.config.extra_browser_args,
			}
		],
	}

	browser = await browser_class.launch(
		headless=self.config.headless,
		channel='chrome',
		args=args[self.config.browser_class],
		proxy=self.config.proxy.model_dump() if self.config.proxy else None,
		handle_sigterm=False,
		handle_sigint=False,
	)
	return browser

