@self.registry.action(
	'Save the raw HTML content of the current page to a local file',
	param_model=NoParamsAction,
)
async def save_html_to_file(_: NoParamsAction, browser: BrowserContext) -> ActionResult:
	"""Retrieves and returns the full HTML content of the current page to a file"""
	try:
		page = await browser.get_current_page()
		html_content = await page.content()

		# Create a filename based on the page URL
		short_url = re.sub(r'^https?://(?:www\.)?|/$', '', page.url)
		slug = re.sub(r'[^a-zA-Z0-9]+', '-', short_url).strip('-').lower()[:64]
		timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
		sanitized_filename = f'{slug}_{timestamp}.html'

		# Save HTML to file
		with open(sanitized_filename, 'w', encoding='utf-8') as f:
			f.write(html_content)

		msg = f'Saved HTML content of page with URL {page.url} to ./{sanitized_filename}'

		logger.info(msg)
		return ActionResult(extracted_content=msg, include_in_memory=True)
	except Exception as e:
		error_msg = f'Failed to save HTML content: {str(e)}'
		logger.error(error_msg)
		return ActionResult(error=error_msg, extracted_content='')

def __init__(self, context: PlaywrightBrowserContext, cached_state: BrowserState | None = None):
	init_script = """
		(() => {
			if (!window.getEventListeners) {
				window.getEventListeners = function (node) {
					return node.__listeners || {};
				};

				// Save the original addEventListener
				const originalAddEventListener = Element.prototype.addEventListener;

				const eventProxy = {
					addEventListener: function (type, listener, options = {}) {
						// Initialize __listeners if not exists
						const defaultOptions = { once: false, passive: false, capture: false };
						if(typeof options === 'boolean') {
							options = { capture: options };
						}
						options = { ...defaultOptions, ...options };
						if (!this.__listeners) {
							this.__listeners = {};
						}

						// Initialize array for this event type if not exists
						if (!this.__listeners[type]) {
							this.__listeners[type] = [];
						}


						// Add the listener to __listeners
						this.__listeners[type].push({
							listener: listener,
							type: type,
							...options
						});

						// Call original addEventListener using the saved reference
						return originalAddEventListener.call(this, type, listener, options);
					}
				};

				Element.prototype.addEventListener = eventProxy.addEventListener;
			}
		})()
		"""
	self.active_tab = None
	self.context = context
	self.cached_state = cached_state
	self.context.on('page', lambda page: page.add_init_script(init_script))

async def _construct_dom_tree(
	self,
	eval_page: dict,
) -> tuple[DOMElementNode, SelectorMap]:
	js_node_map = eval_page['map']
	js_root_id = eval_page['rootId']

	selector_map = {}
	node_map = {}

	for id, node_data in js_node_map.items():
		node, children_ids = self._parse_node(node_data)
		if node is None:
			continue

		node_map[id] = node

		if isinstance(node, DOMElementNode) and node.highlight_index is not None:
			selector_map[node.highlight_index] = node

		# NOTE: We know that we are building the tree bottom up
		#       and all children are already processed.
		if isinstance(node, DOMElementNode):
			for child_id in children_ids:
				if child_id not in node_map:
					continue

				child_node = node_map[child_id]

				child_node.parent = node
				node.children.append(child_node)

	html_to_dict = node_map[str(js_root_id)]

	del node_map
	del js_node_map
	del js_root_id

	gc.collect()

	if html_to_dict is None or not isinstance(html_to_dict, DOMElementNode):
		raise ValueError('Failed to parse HTML to dictionary')

	return html_to_dict, selector_map

