async def send_telemetry_data(self, payload: BaseModel, path: str | None = None) -> None:
    if self.do_not_track:
        logger.debug("Telemetry tracking is disabled.")
        return

    url = f"{self.base_url}"
    if path:
        url = f"{url}/{path}"
    try:
        payload_dict = payload.model_dump(by_alias=True, exclude_none=True, exclude_unset=True)
        response = await self.client.get(url, params=payload_dict)
        if response.status_code != httpx.codes.OK:
            logger.error(f"Failed to send telemetry data: {response.status_code} {response.text}")
        else:
            logger.debug("Telemetry data sent successfully.")
    except httpx.HTTPStatusError:
        logger.exception("HTTP error occurred")
    except httpx.RequestError:
        logger.exception("Request error occurred")
    except Exception:  # noqa: BLE001
        logger.exception("Unexpected error occurred")

def end(
    self,
    inputs: dict[str, Any],
    outputs: dict[str, Any],
    error: Exception | None = None,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not self._ready:
        return
    self.trace.root_span.end(
        input=self._convert_to_langwatch_types(inputs),
        output=self._convert_to_langwatch_types(outputs),
        error=error,
    )

    if metadata and "flow_name" in metadata:
        self.trace.update(metadata=(self.trace.metadata or {}) | {"labels": [f"Flow: {metadata['flow_name']}"]})

    if self.trace.api_key or self._client.api_key:
        self.trace.deferred_send_spans()

